import sys
input = sys.stdin.read

def solve():
    data = input().strip().split()
    n = int(data[0])
    k = int(data[1])

    if k > n * n:
        print(-1)
        return

    # Create an n x n matrix of zeroes
    matrix = [[0] * n for _ in range(n)]

    # Fill the matrix to be lexicographically maximal and symmetric
    for i in range(n):
        if k <= 0:
            break
        # Fill the diagonal element
        if k > 0:
            matrix[i][i] = 1
            k -= 1

        # Fill the symmetric pairs (i, j) and (j, i)
        for j in range(i + 1, n):
            if k > 1:
                matrix[i][j] = 1
                matrix[j][i] = 1
                k -= 2
            else:
                break

    if k > 0:
        print(-1)
    else:
        for row in matrix:
            print(' '.join(map(str, row)))

